const cfg = $('Set Config').first().json;
const pins1 = $('Get Pins').all().map(i => ({ ...i.json, _sourceTab: cfg.pinsTab }));
const pins2 = $('Get Pins 2').all().map(i => ({ ...i.json, _sourceTab: cfg.pinsTab2 }));
const pins = [...pins1, ...pins2];
const boards = $('Get Boards').all().map(i => i.json);
function norm(s){ return (s==null?'':String(s)).replace(/[\u2013-\u2015]/g,'-').replace(/\s+/g,' ').trim().toLowerCase(); }
function bName(r){ return r['Board Name'] || r['Pinterest Board'] || r['Board'] || ''; }
function bId(r){ return r['Board ID'] || r['Tailwind Board ID'] || ''; }
function resolveBoardId(pin){
  const direct = (pin['Board ID']==null?'':String(pin['Board ID'])).trim();
  if (direct) return direct;
  const name = norm(pin['Board']);
  if (!name) return '';
  let b = boards.find(r => norm(bName(r)) === name);
  if (!b) b = boards.find(r => { const bn = norm(bName(r)); return bn && (bn.includes(name) || name.includes(bn)); });
  return b ? String(bId(b)).trim() : '';
}
function toSendAt(v){
  if (v==null || v==='') return '';
  const s = String(v).trim();
  const zone = 'America/Toronto'; // sheet stores naive local time -- anchor explicitly, don't rely on n8n's ambient default zone
  let dt = DateTime.fromISO(s, { zone });
  if(!dt.isValid) dt = DateTime.fromFormat(s,'yyyy-LL-dd HH:mm', { zone });
  if(!dt.isValid) dt = DateTime.fromFormat(s,'yyyy-LL-dd H:mm', { zone });
  if(!dt.isValid) dt = DateTime.fromFormat(s,'M/d/yyyy HH:mm:ss', { zone });
  if(!dt.isValid) dt = DateTime.fromFormat(s,'M/d/yyyy H:mm:ss', { zone });
  if(!dt.isValid) dt = DateTime.fromFormat(s,'M/d/yyyy H:mm', { zone });
  if(!dt.isValid){ const d=new Date(s); if(!isNaN(d.getTime())) dt=DateTime.fromJSDate(d, { zone }); }
  if(!dt || !dt.isValid) return '';
  return dt.toUTC().toFormat("yyyy-LL-dd'T'HH:mm:ss'Z'");
}
function bigImg(u){ u=String(u||''); if(/cdn\.shopify\.com/i.test(u)){ return u.split('?')[0] + '?width=1000'; } return u; }
const nowPlus15 = $now.plus({ minutes: 15 });
// Every overdue row used to get the IDENTICAL $now+24h timestamp -- hundreds of posts
// landing on the exact same minute is what tripped Pinterest's spam block on Sept 11.
// This cursor gives each one its own slot instead, spaced apart, still honoring the
// 24h-minimum-approval-window business rule as the earliest possible slot.
let rescheduleCursor = $now.plus({ hours: 24 });
const rescheduleSpacingMinutes = cfg.rescheduleSpacingMinutes || 20;
const out = [];
for (const pin of pins) {
  if (norm(pin['Approval']) !== 'approved') continue;
  const st = norm(pin['Status']);
  if (st !== 'review' && st !== 'error') continue;

  // A row already tagged with this run's monthly-quota marker (see Build
  // Result) is known to be blocked for the rest of the CURRENT calendar
  // month -- Metricool won't accept it no matter how many times it's
  // retried. Resending it anyway was exactly what caused ~700 "post not
  // published" notification emails in a single day once the backlog
  // built up: every row still eligible got re-attempted, and re-failed,
  // every single day. Skip it silently -- no Metricool call, no sheet
  // write -- until the marker's month no longer matches today's, at
  // which point it falls through to the normal ready/retry logic below
  // and gets a fresh attempt automatically.
  const quotaMatch = st === 'error' && /^Metricool monthly quota reached \((\d{4}-\d{2})\)/.exec(String(pin['Error'] || ''));
  if (quotaMatch && quotaMatch[1] === $now.setZone('America/Toronto').toFormat('yyyy-LL')) continue;

  // Computed up front (before the cutoff branch) so a legacy row's explanatory
  // note can mention its REAL underlying problems too (e.g. a missing board),
  // not just its age -- fixing only the age wouldn't make it publishable anyway.
  const boardId = resolveBoardId(pin);
  const mediaUrl = bigImg(pin['Image 1 URL'] || '');
  const rawSendAt = toSendAt(pin['Scheduled Date']);

  if (cfg.newRowsOnlyAfter) {
    // Existing backlog rows are left completely alone -- not retried, not
    // rescheduled. Only rows created on/after this cutoff are eligible for
    // actual processing. A missing/unparseable Created Time is treated as
    // pre-cutoff (old), not as eligible.
    const cutoff = DateTime.fromISO(cfg.newRowsOnlyAfter);
    const created = DateTime.fromISO(String(pin['Created Time'] || ''));
    if (!created.isValid || created < cutoff) {
      // Silently skipping an overdue legacy row is confusing on the sheet --
      // nothing changes, no error, no explanation. So if its own Scheduled
      // Date has already passed, leave ONE explanatory note (never rewritten
      // again once present, same dedupe principle as below) instead of
      // leaving it looking untouched with no indication why.
      const legacyOverdue = rawSendAt && DateTime.fromISO(rawSendAt) <= $now;
      if (legacyOverdue) {
        const otherIssues = [];
        if (!mediaUrl) otherIssues.push('No image URL');
        if (!boardId) otherIssues.push('Board not found: ' + (pin['Board'] || '(blank)'));
        if (!rawSendAt) otherIssues.push('Invalid scheduled date');
        const legacyNote = 'Not auto-processed: pre-existing row (created before ' + cfg.newRowsOnlyAfter + '). Scheduled time has passed -- update manually if you want this published.'
          + (otherIssues.length ? ' Also: ' + otherIssues.join('; ') + '.' : '');
        if (String(pin['Error'] || '') !== legacyNote) {
          out.push({ json: {
            row_number: pin['row_number'], sourceTab: pin._sourceTab, pinId: pin['Pin ID'],
            ready: false, reason: legacyNote,
            mediaUrl: '', title: '', description: '', url: '', boardId: '', altText: '', sendAt: ''
          } });
        }
      }
      continue;
    }
  }

  let sendAt = rawSendAt;
  let ready = true, reason = '';
  if (!mediaUrl) { ready=false; reason='No image URL'; }
  else if (!boardId) { ready=false; reason='Board not found: ' + (pin['Board']||'(blank)'); }
  else if (!sendAt) { ready=false; reason='Invalid scheduled date'; }
  else if (DateTime.fromISO(sendAt) <= nowPlus15) {
    // Overdue -- give the human at least a full 24h approval window instead of
    // rejecting it forever with no recovery path (business rule: 24h minimum),
    // but give EACH overdue row its own spaced-out slot -- never reuse the same
    // instant for the next one.
    sendAt = rescheduleCursor.toUTC().toFormat("yyyy-LL-dd'T'HH:mm:ss'Z'");
    rescheduleCursor = rescheduleCursor.plus({ minutes: rescheduleSpacingMinutes });
  }
  if (!ready && reason === String(pin['Error'] || '')) {
    // This exact failure is already recorded on the row -- nothing changed
    // since last run (e.g. a permanently blank Board that only a human can
    // fix), so don't burn a sheet write re-stating the same dead error every
    // single day. Only a NEW or CHANGED reason gets written.
    continue;
  }
  out.push({ json: {
    row_number: pin['row_number'],
    sourceTab: pin._sourceTab,
    pinId: pin['Pin ID'], ready, reason,
    mediaUrl,
    title: String(pin['Pin Title']||'').slice(0,100),
    description: String(pin['Pin Description']||'').slice(0,500),
    url: pin['Blog Link'] || pin['Product Link'] || '',
    boardId, altText: String(pin['Alt Text']||'').slice(0,500),
    sendAt,
    // Kept so a failed Create Pin call (Build Result) can write the sheet's
    // Scheduled Date column back unchanged instead of blanking it -- only a
    // row that actually got scheduled should have this cell overwritten.
    scheduledDateRaw: pin['Scheduled Date'] || ''
  } });
}

// Cap how many READY pins actually get published this run -- Create Pin does
// real network calls to Metricool per pin, so a sudden backlog (e.g. right
// after this fix ships) could otherwise blow past n8n's execution memory/time
// limits or hammer Metricool with hundreds of requests in one run. Not-ready
// items are cheap (no external call, just a status write) so they're never
// capped. Deferred ready items are left untouched -- still Review/Error in
// the sheet -- so the NEXT run picks them up, prioritizing the most overdue.
// -- Monthly budget check: Metricool's cap counts EVERY Pinterest post attempt
// for the account, published AND errored alike (confirmed 2026-09-21 -- the
// September spam-block errors alone used ~650 of the 1050 slots). Attempting
// a Create Pin call that's doomed to fail from quota still burns one of those
// slots, so this checks usage BEFORE calling Metricool at all, not after.
const budgetPosts = safe(() => $('Get Metricool Posts (Budget Check)').all(), []);
function safe(fn, d) { try { const v = fn(); return v === undefined ? d : v; } catch (e) { return d; } }
const usedByMonth = {};
const seenBudgetIds = new Set();
for (const it of budgetPosts) {
  const j = it.json || {};
  if (j.error) continue;
  const list = Array.isArray(j.data) ? j.data : Array.isArray(j.posts) ? j.posts : Array.isArray(j) ? j : (j.id ? [j] : []);
  for (const p of list) {
    const key = String(p.id); if (seenBudgetIds.has(key)) continue; seenBudgetIds.add(key);
    if (!(p.providers || []).some(x => String(x.network).toLowerCase() === 'pinterest')) continue;
    const mo = String((p.publicationDate || {}).dateTime || '').slice(0, 7);
    if (mo) usedByMonth[mo] = (usedByMonth[mo] || 0) + 1;
  }
}
const monthlyCap = Number(cfg.pinterestMonthlyCap) || 900, reserve = Number(cfg.reservedForNewPins) || 0;
const budgetRemaining = {}; // lazily computed per month below, decremented as pins are accepted this run

const maxPerRun = cfg.maxPublishPerRun || 50;
const notReady = out.filter(i => !i.json.ready);
const readySorted = out.filter(i => i.json.ready)
  .sort((a, b) => (a.json.sendAt || '').localeCompare(b.json.sendAt || ''));

const ready = [];
for (const item of readySorted) {
  if (ready.length >= maxPerRun) break;
  const mo = String(item.json.sendAt || '').slice(0, 7);
  if (mo) {
    if (!(mo in budgetRemaining)) budgetRemaining[mo] = monthlyCap - reserve - (usedByMonth[mo] || 0);
    if (budgetRemaining[mo] <= 0) continue; // this month is full -- leave the row untouched, try again next run (maybe next month)
    budgetRemaining[mo]--;
  }
  ready.push(item);
}
return [...notReady, ...ready];

// One input item per ready pin, in the same order "IF Ready" emitted them
// (Normalize Image doesn't filter or reorder). Combine the normalized image
// URL with the rest of the pin's data from "IF Ready" by index, and convert
// the UTC sendAt into the local time + timezone Metricool expects.
const pins = $('IF Ready').all();
const tz = 'America/Toronto';

return $input.all().map((item, index) => {
  const pin = (pins[index] && pins[index].json) || {};
  const normalizedUrl = (item.json && item.json.data) || pin.mediaUrl;
  const localDt = DateTime.fromISO(pin.sendAt, { zone: 'utc' }).setZone(tz).toFormat("yyyy-LL-dd'T'HH:mm:ss");
  return { json: {
    text: pin.description,
    publicationDate: { dateTime: localDt, timezone: tz },
    providers: [{ network: 'pinterest' }],
    media: [normalizedUrl],
    mediaAltText: [pin.altText],
    autoPublish: true,
    draft: false,
    pinterestData: {
      boardId: pin.boardId,
      pinTitle: pin.title,
      pinLink: pin.url
    }
  } };
});

// Each input item is one Metricool API response from "Create Pin",
// in the same order as the pins that fed it. The pin metadata
// (Pin ID, row_number, blog url) lives on "IF Ready", not on the
// HTTP response, so pull it from there by index.
const responses = $input.all();
const pins = $('IF Ready').all();
const blogId = $('Set Config').first().json.blogId;

// A failed Create Pin call reaches here as a raw axios-shaped error object
// (message/name/stack/code/status), not a clean JSON body -- Metricool's
// actual error detail is buried as an escaped JSON string inside `message`
// (e.g. `400 - "{\"status\":...,\"detail\":\"...\"}"`). Pull that detail out
// so the sheet shows a human sentence instead of a stack-trace blob.
function humanError(resp) {
  const data = resp?.response?.data || resp?.error?.response?.data;
  const raw = String(resp?.message || resp?.error?.message || resp?.error || '');
  let detail = null;
  if (data && typeof data === 'object') {
    detail = data.detail || data.message || data.title;
  } else {
    const jsonMatch = raw.match(/\{.*\}/s);
    if (jsonMatch) {
      try {
        const parsed = JSON.parse(jsonMatch[0].replace(/\\"/g, '"'));
        detail = parsed && (parsed.detail || parsed.message || parsed.title);
      } catch (e) { /* not parseable -- fall through to the raw text below */ }
    }
  }
  detail = detail || raw || 'Metricool API error';

  // The scheduled-post cap is shared across every network on this Metricool
  // account (Pinterest, Facebook, Instagram, YouTube...) and won't lift
  // until the calendar month rolls over. Tag it with the month it happened
  // in so Prepare can recognize this exact row next run and stop retrying
  // it daily -- see the quota-marker skip there.
  if (/reached the limit of \d+ posts scheduled for the month/i.test(detail)) {
    const monthKey = $now.setZone('America/Toronto').toFormat('yyyy-LL');
    return 'Metricool monthly quota reached (' + monthKey + ') -- will auto-retry once it resets next month.';
  }
  return detail;
}

return responses.map((item, index) => {
  const response = item.json || {};
  const pin = (pins[index] && pins[index].json) || {};
  const post = response.data || {};
  const ok = !!post.id;

  return {
    json: {
      "Row Number": pin.row_number,
      "_sourceTab": pin.sourceTab,
      "Pin ID": pin.pinId,
      "Pin URL": pin.url,
      "Status": ok ? "Scheduled" : "Error",
      "Metricool Post ID": post.id || "",
      "Metricool Link": post.uuid ? ('https://app.metricool.com/planner/calendar?blogId=' + blogId + '&openWithPostUuid=' + post.uuid) : "",
      "Error": ok ? "" : humanError(response),
      // Only overwrite the sheet's Scheduled Date when the post actually got
      // scheduled (it may have been bumped forward off its original stale
      // value -- see Prepare). On failure, echo the original cell back
      // unchanged instead of blanking it; the row keeps retrying daily
      // (Prepare treats Status "Error" the same as "Review") and this column
      // will fill in with the real date the moment it succeeds -- e.g. once
      // Metricool's monthly quota resets, no manual fix needed.
      "Scheduled Date": ok && pin.sendAt
        ? DateTime.fromISO(pin.sendAt).setZone('America/Toronto').toFormat('M/d/yyyy HH:mm:ss')
        : (pin.scheduledDateRaw || '')
    }
  };
});

// Emit one row per not-ready pin (runs once for all items).
return $input.all().map(item => {
  const p = item.json || {};
  return {
    json: {
      'Row Number': p.row_number,
      '_sourceTab': p.sourceTab,
      'Pin ID': p.pinId,
      'Status': 'Review',
      'Metricool Post ID': '',
      'Metricool Link': '',
      'Error': p.reason || 'Not ready'
    }
  };
});

// One request window per 14 days, covering from the start of THIS month through
// the end of NEXT month -- wide enough to cover both an overdue-reschedule burst
// (which can push a little into next month near a month boundary) and normally
// already-dated rows, without pulling the whole account's history every run.
const cfg = $('Set Config').first().json;
const start = $now.startOf('month');
const end = $now.plus({ months: 1 }).endOf('month');
const out = [];
let cur = start;
while (cur < end) {
  const winEnd = DateTime.min(cur.plus({ days: 13 }).endOf('day'), end);
  out.push({ json: { start: cur.toFormat("yyyy-LL-dd'T'HH:mm:ss"), end: winEnd.toFormat("yyyy-LL-dd'T'HH:mm:ss") } });
  cur = cur.plus({ days: 14 }).startOf('day');
}
return out;
